const fs = require('fs');
const source = fs.readFileSync('js/app.js', 'utf8');

// Extract all @planks annotations
const plankRegex = /@planks\(\"([^\"]+)\"\)/g;
const planks = [];
let m;
while ((m = plankRegex.exec(source)) !== null) {
  planks.push(m[1]);
}

// Step patterns that have non-conformance matches (from usage output)
const usedStepPatterns = [
  'the app has loaded with no persisted todos',
  'I create a todo titled {string}',
  'I mark the first todo as completed',
  'I mark every todo as completed',
  'I unmark one todo',
  'I type {string} into the new-todo input',
  'I press Enter',
  'I click the toggle checkbox for the todo',
  'I click the toggle-all checkbox',
  'I click the clear-completed button',
  'I double-click the todo label',
  'I type {string} into the edit input',
  'I press Enter in the edit input',
  'the edit input loses focus',
  'I press Escape in the edit input',
  'I clear the edit input',
  'the route is {string}',
  'I mark the first visible todo as completed',
  'the app loads',
  'I reload the app',
  'localStorage has 2 persisted todos',
];

// Check all planks match a used pattern
console.log('=== Plank-to-Step-Usage Join ===');
planks.forEach(p => {
  const match = usedStepPatterns.includes(p);
  console.log((match ? '✓' : '✗') + ' ' + JSON.stringify(p));
});

// Check for used patterns not planked
console.log('\\n=== Unplanked driving steps ===');
const drivingSteps = [
  'the app has loaded with no persisted todos',
  'I create a todo titled {string}',
  'I mark the first todo as completed',
  'I mark every todo as completed',
  'I unmark one todo',
  'I type {string} into the new-todo input',
  'I press Enter',
  'I click the toggle checkbox for the todo',
  'I click the toggle-all checkbox',
  'I click the clear-completed button',
  'I double-click the todo label',
  'I type {string} into the edit input',
  'I press Enter in the edit input',
  'the edit input loses focus',
  'I press Escape in the edit input',
  'I clear the edit input',
  'the route is {string}',
  'I mark the first visible todo as completed',
  'the app loads',
  'I reload the app',
  'localStorage has 2 persisted todos',
];
drivingSteps.forEach(p => {
  if (!planks.includes(p)) {
    console.log('✗ ' + JSON.stringify(p) + ' (unplanked)');
  }
});
console.log('\\nAll driving steps planked: ' + drivingSteps.every(p => planks.includes(p)));
"

